            .host-panel{padding:16px;margin-bottom:18px}.host-facts{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.fact{display:grid;gap:4px;min-width:0}.fact-label{font-size:12px;color:#667389}.fact-value{overflow-wrap:anywhere}
