            .agent-group{background:#fff;border:1px solid #dfe5ed;border-radius:12px;overflow:hidden}.agent-summary{padding:16px;display:grid;gap:13px}.agent-summary-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.agent-summary h3{margin:0 0 3px;font-size:18px}.agent-facts{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.agent-facts .fact{padding-top:9px;border-top:1px solid #edf0f4}
            .models{border-top:1px solid #dfe5ed}.model-cluster{border-bottom:1px solid #dfe5ed}.model-cluster:last-child{border-bottom:0}.model-cluster-title{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 16px;background:#f7f9fc}.model-cluster-title h4{margin:0;font-size:16px}.model-cluster-meta{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.model-row{display:grid;grid-template-columns:1fr .85fr 1.35fr 1.35fr .9fr 1.15fr;gap:10px;padding:12px 16px;border-top:1px solid #edf0f4;align-items:start}.model-head{padding-top:9px;padding-bottom:9px;background:#fff;color:#536176;font-size:12px;font-weight:600}.model-row.is-priority{box-shadow:inset 3px 0 #1d5fd1}.model-cell{min-width:0;overflow-wrap:anywhere}.model-cell[data-label]::before{display:none}.model-cell.endpoint-child{padding-left:14px;border-left:2px solid #dce7f8}.cell-stack{display:grid;gap:4px}.current-label{color:#1d5fd1;font-size:12px;font-weight:600}.inactive-label{color:#667389;font-size:12px;font-weight:600}.inactive-configs{border-top:1px solid #dfe5ed;background:#fbfcfe}.inactive-configs>summary{cursor:pointer;padding:12px 16px;color:#455369;font-weight:600}.inactive-configs[open]>summary{border-bottom:1px solid #dfe5ed}.inactive-configs .models{border-top:0}.inactive-configs .model-row.is-priority{box-shadow:none}.empty-config{padding:14px 16px;border-top:1px solid #dfe5ed;color:#667389}
            .secondary-info{display:grid;gap:12px;margin-top:18px}.secondary-info details{background:#fff;border:1px solid #dfe5ed;border-radius:12px;padding:0 16px}.secondary-info summary{cursor:pointer;font-weight:600;padding:14px 0}.runtime-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;padding:0 0 16px}.command-list{display:grid;gap:10px;padding-bottom:14px}.command-record{border:1px solid #e2e7ee;border-radius:10px;padding:12px;background:#fbfcfe}.command-record-head{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin-bottom:12px}.command-record-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.audit-list{display:grid;gap:8px;padding-bottom:14px}.audit-row{display:grid;grid-template-columns:1.1fr 1fr 1fr 2fr;gap:10px;padding:10px 0;border-top:1px solid #edf0f4;overflow-wrap:anywhere}.audit-head{color:#536176;font-size:12px;font-weight:600}
            @media(max-width:1050px){.agent-facts{grid-template-columns:repeat(3,minmax(0,1fr))}.host-facts,.runtime-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
