              .model-head,.audit-head{display:none}.model-row,.audit-row,.command-record-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.model-cell[data-label]::before,.audit-cell[data-label]::before{content:attr(data-label);display:block;color:#667389;font-size:12px;margin-bottom:3px}.model-row{padding:14px 16px}.model-row+.model-row{border-top:6px solid #f4f6f9}
