              table,thead,tbody,tr,th,td{display:block}thead{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}tbody{display:grid;gap:10px}tbody tr{border:1px solid #dfe5ed;border-radius:10px;padding:10px}tbody td{display:grid;grid-template-columns:105px minmax(0,1fr);gap:8px;border:0;padding:5px}tbody td::before{content:attr(data-label);color:#667389;font-size:12px}tbody tr:hover{background:#fff}
              .model-row,.audit-row,.command-record-grid{grid-template-columns:1fr}.detail-title h2{font-size:21px}.section-heading{align-items:flex-start;flex-direction:column}
            }
            @media(max-width:420px){.cards,.detail-metrics,.host-facts,.runtime-grid,.agent-facts{grid-template-columns:1fr}.detail-actions{display:grid;grid-template-columns:1fr;width:100%}.detail-actions button{width:100%}}
          </style>
        </head>
        <body><main class="shell">
          <section id="authView" class="auth-view">
            <form id="authForm" class="surface auth-card">
              <h1>EndpointAIDLP 资产控制台</h1>
              <p class="muted">使用管理员凭据连接控制服务。</p>
              <div class="field"><label for="token">管理员 Token</label><input id="token" type="password" autocomplete="current-password" required></div>
              <div class="field"><label for="actor">操作人工号</label><input id="actor" maxlength="64" autocomplete="username" required></div>
              <button class="primary" type="submit">登录</button>
              <p id="authMessage" class="message" role="alert"></p>
            </form>
          </section>

          <section id="appShell" class="hidden">
            <header class="app-header">
              <h1>EndpointAIDLP 资产控制台</h1>
              <div id="appMessage" class="app-message" role="status" aria-live="polite"></div>
            </header>

            <section id="listView">
              <div class="cards">
                <div class="surface metric"><span>终端总数</span><b id="total">0</b></div>
                <div class="surface metric"><span>在线</span><b id="online" class="ok-text">0</b></div>
                <div class="surface metric"><span>离线/陈旧</span><b id="offline" class="warn-text">0</b></div>
                <div class="surface metric"><span>代理已停用</span><b id="disabled">0</b></div>
              </div>
              <section class="surface allowlist-panel" aria-labelledby="allowlistHeading">
                <div class="allowlist-header">
                  <div class="allowlist-title"><h2 id="allowlistHeading">代理白名单</h2><span class="muted small">精确匹配 Base URL，命中后恢复原地址并绕过 EndpointAIDLP</span></div>
                  <span id="allowlistVersion" class="status allowlist-version">策略未加载</span>
                </div>
                <form id="allowlistForm" class="allowlist-form">
                  <input id="allowlistInput" aria-label="新增白名单 Base URL" maxlength="2048" placeholder="https://api.example.invalid/v1">
                  <button class="secondary" type="submit">添加地址</button>
                </form>
                <div id="allowlistEntries" class="allowlist-entries"></div>
                <div class="allowlist-footer">
                  <span id="allowlistState" class="muted small" role="status" aria-live="polite">允许 HTTP/HTTPS；不支持通配符、查询参数或 Fragment。</span>
                  <div class="allowlist-actions"><button id="reloadAllowlist" class="secondary" type="button">重新加载</button><button id="saveAllowlist" class="primary" type="button" disabled>保存并下发</button></div>
                </div>
              </section>
              <div class="surface list-panel">
                <div class="toolbar">
                  <input id="search" aria-label="搜索主机名或 Device ID" placeholder="搜索主机名或 Device ID">
                  <select id="state" aria-label="在线状态"><option value="">全部状态</option><option value="online">在线</option><option value="stale">陈旧</option><option value="offline">离线</option><option value="legacyClient">旧版客户端</option></select>
                  <button id="refreshList" class="secondary" type="button">刷新</button>
                </div>
                <div class="table-wrap">
                  <table aria-label="终端列表"><thead><tr><th style="width:19%">主机</th><th style="width:12%">客户端</th><th style="width:12%">在线状态</th><th style="width:9%">Agent</th><th style="width:10%">模型配置</th><th style="width:13%">代理状态</th><th style="width:17%">最后心跳</th><th style="width:8%">操作</th></tr></thead><tbody id="devices"></tbody></table>
                  <div id="deviceEmpty" class="empty hidden">没有符合条件的终端。</div>
                </div>
              </div>
            </section>

            <section id="detailView" class="hidden">
              <div class="detail-header">
                <div class="detail-title"><h2 id="detailHostname"></h2><div id="detailMeta" class="detail-meta"></div><div id="detailFreshness" class="detail-freshness"></div></div>
                <div class="detail-actions"><button id="backToList" class="secondary" type="button">返回终端列表</button><button id="refreshDetail" class="secondary" type="button">刷新详情</button><button id="disableProxy" class="danger-button" type="button">停用代理</button><button id="enableProxy" class="primary" type="button">重新启用</button></div>
              </div>
              <div id="detailStaleBanner" class="stale-banner hidden" role="status">数据已陈旧，当前配置可能不是终端最新状态。</div>
              <div id="hostPanel" class="surface host-panel"></div>
              <div class="cards detail-metrics">
                <div class="surface metric"><span>已发现 Agent</span><b id="detailAgentCount">0</b><small id="detailAgentNote" class="muted"></small></div>
                <div class="surface metric"><span>当前模型</span><b id="detailEndpointCount">0</b><small id="detailEndpointNote" class="muted"></small></div>
                <div class="surface metric"><span>本次启动请求</span><b id="detailRequestCount">0</b><small id="detailRequestNote" class="muted"></small></div>
              </div>
              <div class="section-heading"><h2>Agent 与模型代理关系</h2><span class="muted small">主区仅显示当前启用配置，未启用配置在 Agent 内折叠展示</span></div>
              <div id="agentGroups" class="agent-list"></div>
              <div id="secondaryInfo" class="secondary-info"></div>
            </section>
          </section>
        </main>
        <script>
          const $=id=>document.getElementById(id),DetailRefreshIntervalMilliseconds=15000;let devices=[],currentDevice=null,currentDetail=null,currentCommands=[],currentAudit=[],currentPolicy=null,allowlistDraft=[],allowlistDirty=false,commandCreateInFlight=false,detailRefreshTimer=null,detailFetchInFlight=null,lastDetailRevision=null,lastDetailRefreshAt=null,inactiveOpenKeys=new Set();
          $('token').value=sessionStorage.getItem('sf-admin-token')||'';$('actor').value=sessionStorage.getItem('sf-admin-actor')||'';
          function value(v,fallback='未提供'){return v===null||v===undefined||v===''?fallback:String(v)}
          function node(tag,cls='',content){const e=document.createElement(tag);if(cls)e.className=cls;if(content!==undefined)e.textContent=content;return e}
          function setText(id,v){$(id).textContent=value(v,'0')}
          function setAppMessage(message,error=false){$('appMessage').textContent=message||'';$('appMessage').classList.toggle('error',error)}
          function showLogin(message=''){stopDetailAutoRefresh();$('authView').classList.remove('hidden');$('appShell').classList.add('hidden');$('authMessage').textContent=message;$('authMessage').classList.toggle('error',!!message);currentDevice=null;currentDetail=null;currentCommands=[];currentAudit=[];lastDetailRevision=null}
          function showList(){stopDetailAutoRefresh();$('authView').classList.add('hidden');$('appShell').classList.remove('hidden');$('listView').classList.remove('hidden');$('detailView').classList.add('hidden');currentDevice=null;currentDetail=null;currentCommands=[];currentAudit=[];lastDetailRevision=null}
          function showDetailView(){$('authView').classList.add('hidden');$('appShell').classList.remove('hidden');$('listView').classList.add('hidden');$('detailView').classList.remove('hidden');startDetailAutoRefresh()}
          function headers(json=false){const h={Authorization:'Bearer '+$('token').value,'X-SF-Admin-Actor':$('actor').value||'admin-token'};if(json)h['Content-Type']='application/json';return h}
          async function api(path,options={}){const r=await fetch(path,{...options,headers:{...headers(!!options.body),...(options.headers||{})}});if(!r.ok){const body=await r.text();const error=new Error(body||('HTTP '+r.status));error.status=r.status;if(r.status===401||r.status===403)showLogin('登录已失效，请重新登录。');throw error}return r.status===204?null:r.json()}
          function statusClass(status){const s=String(status||'').toLowerCase();if(['online','enabled','listening','attached','succeeded','success','bypassed'].includes(s))return'ok';if(['stale','degraded','pending','discovered','neverobserved','unknown','legacyclient'].includes(s))return'warn';if(['offline','disabled','error','failed','noncompliant','unsupported','connectionfailed','routefailed','gatewayreachedwitherror','disablefailed','enablefailed'].includes(s))return'bad';return''}
          function statusLabel(status){const labels={online:'在线',stale:'陈旧',offline:'离线',legacyClient:'旧版客户端',enabled:'已启用',disabled:'已停用',disableFailed:'停用失败',enableFailed:'启用失败',listening:'监听正常',stopped:'已停止',starting:'启动中',degraded:'降级',unknown:'未知',attached:'已挂载',bypassed:'白名单直连',discovered:'已发现',pending:'待处理',restartRequired:'需重启',nonCompliant:'不合规',unsupported:'不支持',error:'错误',succeeded:'成功',gatewayReachedWithError:'网关返回错误',connectionFailed:'连接失败',routeFailed:'路由失败',allowlistBypassed:'白名单直连',neverObserved:'未观测请求',disableProxy:'停用代理',enableProxy:'重新启用',executing:'执行中',delivered:'已下发',expired:'已过期',cancelled:'已取消'};return labels[status]||value(status)}
          function badge(status,label){const result=node('span','status '+statusClass(status),label||statusLabel(status));if(status==='nonCompliant')result.title='当前配置未精确指向该配置身份的预期路由，或仍指向没有有效配置实体的本地代理地址。';return result}
          function localTime(v){if(!v)return'未提供';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):d.toLocaleString()}
          function onlineStateForDevice(device){const seen=new Date(device?.lastSeenAtUtc).getTime();if(!Number.isFinite(seen))return'offline';const interval=Math.min(3600,Math.max(15,Number(device.heartbeatIntervalSeconds)||60))*1000,elapsed=Date.now()-seen;if(elapsed<=interval*2+30000)return'online';return elapsed<=interval*5+30000?'stale':'offline'}
          function compactId(v){const s=value(v);return s.length>18?s.slice(0,8)+'...'+s.slice(-6):s}
          function td(v,label,cls=''){const e=node('td',cls,value(v));e.dataset.label=label;return e}
          async function connect(){const token=$('token').value.trim(),actor=$('actor').value.trim();if(!token||!actor){showLogin('请输入管理员 Token 和操作人工号。');return}sessionStorage.setItem('sf-admin-token',token);sessionStorage.setItem('sf-admin-actor',actor);$('authMessage').textContent='正在验证...';try{await Promise.all([loadDevices(),loadPolicy()]);showList();setAppMessage('');renderDevices()}catch(e){if(e.status!==401&&e.status!==403)showLogin('连接失败：'+e.message)}}
          async function loadDevices(){devices=await api('/admin/v1/devices');renderDevices()}
          function normalizeBaseUrl(raw){const text=raw.trim();if(!text||text.length>2048||text.includes('?')||text.includes('#'))throw new Error('请输入不含查询参数或 Fragment 的完整 HTTP/HTTPS Base URL。');let url;try{url=new URL(text)}catch{throw new Error('Base URL 格式无效。')}if(!['http:','https:'].includes(url.protocol)||url.username||url.password)throw new Error('仅支持不含账号信息的 HTTP/HTTPS Base URL。');const path=url.pathname==='/'?'':url.pathname.replace(/\/+$/,'');return url.origin+path}
          function renderAllowlist(){const root=$('allowlistEntries');root.replaceChildren();if(!allowlistDraft.length)root.append(node('div','allowlist-empty','当前没有白名单地址，所有 Base URL 都将按策略接入代理。'));for(const url of allowlistDraft){const row=node('div','allowlist-row');row.append(node('code','mono small',url));const remove=node('button','secondary','删除');remove.type='button';remove.setAttribute('aria-label','删除白名单 '+url);remove.onclick=()=>{allowlistDraft=allowlistDraft.filter(item=>item!==url);allowlistDirty=true;renderAllowlist()};row.append(remove);root.append(row)}$('allowlistVersion').textContent=currentPolicy?'策略 v'+currentPolicy.policyVersion:'策略未加载';$('saveAllowlist').disabled=!currentPolicy||!allowlistDirty;$('allowlistState').textContent=allowlistDirty?'有未保存的白名单变更':'允许 HTTP/HTTPS；不支持通配符、查询参数或 Fragment。';$('allowlistState').className=(allowlistDirty?'dirty':'muted')+' small'}
          async function loadPolicy(){currentPolicy=await api('/admin/v1/policy');allowlistDraft=[...(currentPolicy.allowlistedBaseUrls===null||currentPolicy.allowlistedBaseUrls===undefined?['https://ccr.example.invalid']:currentPolicy.allowlistedBaseUrls)];allowlistDirty=false;renderAllowlist()}
          function addAllowlistEntry(){try{const normalized=normalizeBaseUrl($('allowlistInput').value);if(allowlistDraft.includes(normalized)){setAppMessage('该 Base URL 已在白名单中',true);return}if(allowlistDraft.length>=256){setAppMessage('白名单最多允许 256 条地址',true);return}allowlistDraft.push(normalized);allowlistDirty=true;$('allowlistInput').value='';renderAllowlist();setAppMessage('')}catch(e){setAppMessage(e.message,true)}}
