          async function refreshList(){setAppMessage('正在刷新...');try{await loadDevices();setAppMessage('已刷新')}catch(e){if(e.status!==401&&e.status!==403)setAppMessage('刷新失败：'+e.message,true)}}
          async function refreshCurrentDetail(){if(!currentDevice)return;setAppMessage('正在刷新详情...');try{await fetchDetail(true);setAppMessage('详情已刷新')}catch(e){if(e.status!==401&&e.status!==403)setAppMessage('详情刷新失败：'+e.message,true)}}
          async function createCommand(type){if(!currentDevice||commandCreateInFlight)return;const reason=prompt('请输入操作原因');if(!reason)return;const confirmed=prompt('请输入主机名 '+currentDevice.hostname+' 以确认');if(confirmed!==currentDevice.hostname){alert('主机名不匹配');return}const deviceId=currentDevice.deviceId;commandCreateInFlight=true;updateCommandButtons();setAppMessage('正在创建并确认命令...');try{const created=await api('/admin/v1/devices/'+deviceId+'/commands',{method:'POST',body:JSON.stringify({type,reason,expiresInMinutes:30})});if(!created?.commandId||String(created.deviceId).toLowerCase()!==String(deviceId).toLowerCase()||created.status!=='pending'){const error=new Error('POST 返回内容与当前终端或 Pending 状态不一致。');error.confirmationFailure=true;throw error}const commands=await api('/admin/v1/devices/'+deviceId+'/commands'),confirmedCommand=commands.find(command=>String(command.commandId).toLowerCase()===String(created.commandId).toLowerCase()&&String(command.deviceId).toLowerCase()===String(deviceId).toLowerCase());if(!confirmedCommand){const error=new Error('控制端接受了请求，但查询接口未返回同一 Command ID。');error.confirmationFailure=true;throw error}currentCommands=commands;setAppMessage('命令已创建并确认，Command ID：'+created.commandId);await Promise.all([loadDevices(),fetchDetail(true)]);if(currentDevice){const latest=devices.find(device=>device.deviceId===currentDevice.deviceId);if(latest){currentDevice={...currentDevice,...latest};renderDetail(currentDevice,currentDetail,currentCommands,currentAudit)}}}catch(e){if(e.status!==401&&e.status!==403){const prefix=e.status===409?'命令未创建：终端已有活动命令。':e.confirmationFailure?'命令创建结果未确认：':e.status?'命令创建被控制端拒绝：':'命令未发送或网络异常：';setAppMessage(prefix+e.message,true)}}finally{commandCreateInFlight=false;updateCommandButtons()}}
          document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')startDetailAutoRefresh();else stopDetailAutoRefresh()});$('authForm').onsubmit=e=>{e.preventDefault();connect()};$('allowlistForm').onsubmit=e=>{e.preventDefault();addAllowlistEntry()};$('saveAllowlist').onclick=saveAllowlist;$('reloadAllowlist').onclick=reloadAllowlist;$('refreshList').onclick=refreshList;$('search').oninput=renderDevices;$('state').onchange=renderDevices;$('backToList').onclick=()=>{showList();renderDevices();setAppMessage('')};$('refreshDetail').onclick=refreshCurrentDetail;$('disableProxy').onclick=()=>createCommand('disableProxy');$('enableProxy').onclick=()=>createCommand('enableProxy');if($('token').value&&$('actor').value)connect();else showLogin();
        </script></body></html>
        """;
}
